import sqlite3,re
c=sqlite3.connect('/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-ws0/frozen/held-out/play/users/u017/system/state/hermes/state.db'); c.row_factory=sqlite3.Row
msgs=c.execute("select content from messages where session_id=? and role='user' order by id",('422ae5dc-a9af-4716-b777-b482d782265f',)).fetchall(); pairs=[]
for m in msgs:
 t=m['content'] or ''
 for n in range(1,4):
  a=re.search(r'Demo pair '+str(n)+r' input \(\d+x\d+\):\n(.*?)(?=\nDemo pair '+str(n)+r' output)',t,re.S)
  b=re.search(r'Demo pair '+str(n)+r' output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance)',t,re.S)
  if a and b:
   parse=lambda s:[list(map(int,x.split())) for x in s.strip().splitlines()]
   pairs.append((parse(a.group(1)),parse(b.group(1))))
for idx,(g,o) in enumerate(pairs,1):
 h,w=len(g),len(g[0]); marks=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,1)]; print('DEMO',idx)
 for r,c,col in marks:
  want={(y,x) for y in range(h) for x in range(w) if o[y][x]==col and g[y][x]!=col}; print(' marker',col,(r,c),'paint',len(want))
  for rad in range(1,8):
   def patch(y,x):
    return tuple(tuple(1 if (yy,xx)==(r,c) and g[yy][xx]==col else g[yy][xx] for xx in range(max(0,x-rad),min(w,x+rad+1))) for yy in range(max(0,y-rad),min(h,y+rad+1)))
   p=patch(r,c); got={(y,x) for y in range(h) for x in range(w) if g[y][x]==1 and patch(y,x)==p}
   if got==want: print(' exact patch radius',rad); break
   if rad==1: best=(len(got-want),len(want-got),got)
  print(' radius1 mismatch extra/missing',len(best[2]-want),len(want-best[2]))
PY'''
r=terminal(cmd, timeout=180, workdir='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-ws0/frozen/held-out/play/users/u017/system/state/workspace')
print(r.get('output',''), 'exit',r.get('exit_code'))

