import base64, subprocess, textwrap
script = r'''import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-ws0/frozen/held-out/play/users/u017/system/state/hermes/state.db'
c=sqlite3.connect(p)
msg=c.execute("select content from messages where session_id='422ae5dc-a9af-4716-b777-b482d782265f' and role='user'").fetchall()
for (txt,) in msg:
  if not txt or 'Demo pair 1 input' not in txt: continue
  for k in (1,2,3):
    pat=rf'Demo pair {k} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {k} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance\.|\Z)'
    m=re.search(pat,txt,re.S)
    if not m: continue
    h,w=map(int,m.group(1,2)); a=[[int(x) for x in line.split()] for line in m.group(3).splitlines()]; b=[[int(x) for x in line.split()] for line in m.group(4).splitlines()]
    for color in set(sum(a,[]))-{0,1}:
      seeds=[(r,c0) for r in range(h) for c0 in range(w) if a[r][c0]==color]
      if not seeds: continue
      sr,sc=seeds[0]; obs={(r,c0) for r in range(h) for c0 in range(w) if b[r][c0]==color}
      best=[]
      for rh in range(1,min(h,15)+1):
       for rw in range(1,min(w,15)+1):
        for ar in range(rh):
         for ac in range(rw):
          # window has anchor at offset ar,ac, require inbounds at seed
          if sr-ar<0 or sc-ac<0 or sr-ar+rh>h or sc-ac+rw>w: continue
          templ=[[int(a[sr-ar+i][sc-ac+j]!=0) for j in range(rw)] for i in range(rh)]
          # find all matching placement anchors, map colored cells = anchor+offset
          preds=set()
          for r0 in range(h-rh+1):
           for c0 in range(w-rw+1):
            if [[int(a[r0+i][c0+j]!=0) for j in range(rw)] for i in range(rh)]==templ:
             preds.add((r0+ar,c0+ac))
          if preds==obs: best.append((rh*rw,rh,rw,ar,ac,len(preds)))
      print('PAIR',k,'COLOR',color,'seed',seeds,'observed n',len(obs),'obs',sorted(obs))
      print('exact windows',sorted(best)[:6])
'''
enc=base64.b64encode(script.encode()).decode()
r=subprocess.run(['python3','-c',f"import base64;exec(base64.b64decode('{enc}'))"],capture_output=True,text=True)
print(r.stdout)
print(r.stderr)

